  { json: { organisme: 'ASER', url: 'https://www.aser.sn/', secteur_attendu: 'électrification rurale' } },
  { json: { organisme: 'BNDE', url: 'https://www.bnde.sn/', secteur_attendu: 'financement énergie' } },
  { json: { organisme: 'DER/FJ', url: 'https://der.sn/', secteur_attendu: 'énergie / activité productive' } },
  { json: { organisme: 'AFD Sénégal', url: 'https://www.afd.fr/fr/page-region-pays/senegal', secteur_attendu: 'financement climat' } },
  { json: { organisme: 'GIZ Sénégal', url: 'https://www.giz.de/en/worldwide/365.html', secteur_attendu: 'énergie / climat' } }
];

const html = String($json.data ?? $json.body ?? $json.html ?? '');
const decode = (value) => value
  .replace(/&nbsp;/gi, ' ')
  .replace(/&amp;/gi, '&')
  .replace(/&quot;/gi, '"')
  .replace(/&#39;|&apos;/gi, "'")
  .replace(/&lt;/gi, '<')
  .replace(/&gt;/gi, '>');
const text = decode(html
  .replace(/<script\b[^>]*>[\s\S]*?<\/script>/gi, ' ')
  .replace(/<style\b[^>]*>[\s\S]*?<\/style>/gi, ' ')
  .replace(/<[^>]+>/g, ' '))
  .replace(/\s+/g, ' ')
  .trim();
const keywords = ['appel à projets', 'appel a projets', 'appel à candidatures', 'appel a candidatures', 'financement', 'subvention', 'programme', 'fonds', 'grant', 'funding', 'challenge', 'concours', 'accompagnement', 'prêt', 'garantie', 'énergie', 'climat', 'renouvelable'];
const links = [];
const linkPattern = /<a\b[^>]*href=["']([^"']+)["'][^>]*>([\s\S]*?)<\/a>/gi;
let match;
while ((match = linkPattern.exec(html)) !== null) {
  try {
    const url = new URL(decode(match[1]), $json.url);
    const sourceHost = new URL($json.url).hostname.toLowerCase();
    const host = url.hostname.toLowerCase();
    const isIpLiteral = /^\d{1,3}(?:\.\d{1,3}){3}$/.test(host) || host.includes(':');
    const isLocalHost = ['localhost', 'localhost.localdomain'].includes(host) || ['.localhost', '.local', '.internal'].some((suffix) => host.endsWith(suffix));
    const sameHost = host === sourceHost;
    if (!['http:', 'https:'].includes(url.protocol) || isIpLiteral || isLocalHost || url.username || url.password || url.port || (!sameHost && url.protocol !== 'https:')) continue;
    const label = decode(match[2].replace(/<[^>]+>/g, ' ')).replace(/\s+/g, ' ').trim();
    if (label && keywords.some((keyword) => `${label} ${url.href}`.toLocaleLowerCase('fr').includes(keyword))) {
      links.push({ url: url.href, label });
    }
  } catch {}
}
const uniqueLinks = [...new Map(links.map((link) => [link.url, link])).values()].slice(0, 20);
const candidates = uniqueLinks.length ? uniqueLinks : [{ url: $json.url, label: `Page source officielle ${$json.organisme}` }];
return candidates.map((link) => ({ json: { organisme_source: $json.organisme, source_url: $json.url, secteur_attendu: $json.secteur_attendu, candidate_url: link.url, candidate_label: link.label, page_text: text.slice(0, 18000) } }));

const html = String($json.data ?? $json.body ?? $json.html ?? '');
const decode = (value) => value.replace(/&nbsp;/gi, ' ').replace(/&amp;/gi, '&').replace(/&quot;/gi, '"').replace(/&#39;|&apos;/gi, "'").replace(/&lt;/gi, '<').replace(/&gt;/gi, '>');
const page = decode(html.replace(/<script\b[^>]*>[\s\S]*?<\/script>/gi, ' ').replace(/<style\b[^>]*>[\s\S]*?<\/style>/gi, ' ').replace(/<[^>]+>/g, ' ')).replace(/\s+/g, ' ').trim();
return [{ json: { ...$json, candidate_text: page.slice(0, 24000) } }];

const raw = $json.choices?.[0]?.message?.content ?? '{}';
let detection;
try { detection = typeof raw === 'string' ? JSON.parse(raw) : raw; } catch { detection = { is_opportunity: false, reason: 'Réponse JSON invalide', confidence: 0 }; }
return [{ json: { ...$json, detection } }];

const raw = $json.choices?.[0]?.message?.content ?? '{}';
let extracted;
try { extracted = typeof raw === 'string' ? JSON.parse(raw) : raw; } catch { extracted = {}; }
const numberOrNull = (value) => {
  if (value === null || value === undefined || value === '') return null;
  const parsed = Number(String(value).replace(/[^0-9,.-]/g, '').replace(',', '.'));
  return Number.isFinite(parsed) ? parsed : null;
};
const title = String(extracted.titre ?? $json.candidate_label ?? '').trim();
const organization = String(extracted.organisme ?? $json.organisme_source ?? '').trim();
const sourceUrl = String(extracted.url_source ?? $json.candidate_url ?? '').trim();
const deadline = extracted.date_limite || null;
const confidence = numberOrNull(extracted.confiance_extraction);
const amount = numberOrNull(extracted.montant_max);
const rate = numberOrNull(extracted.taux_financement_pct);
        const validDate = !deadline || (/^\d{4}-\d{2}-\d{2}$/.test(String(deadline)) && !Number.isNaN(Date.parse(`${deadline}T00:00:00`)) && new Date(`${deadline}T00:00:00`).toISOString().slice(0, 10) === deadline);
const validUrl = /^https?:\/\//i.test(sourceUrl);
const ready = Boolean(title && organization && validUrl && validDate && (rate === null || (rate >= 0 && rate <= 100)));
return [{ json: {
  _ready_for_ingestion: ready,
  titre: title,
  organisme: organization,
  description: String(extracted.description ?? '').trim(),
  criteres_eligibilite: String(extracted.criteres_eligibilite ?? '').trim(),
  secteur: String(extracted.secteur ?? $json.secteur_attendu ?? '').trim(),
  montant_max: amount,
  devise: String(extracted.devise ?? 'FCFA').trim() || 'FCFA',
  taux_financement_pct: rate,
  date_limite: deadline,
  url_source: sourceUrl,
  confiance_extraction: confidence
} }];
